"OLAYLAR_EK:1394-10-10:0":{"b": ["रोविने युद्ध — वालाकिया अभियान", "343ae7a9"], "d": ["वालाकिया के वोयवोदा मिर्चा के साथ हुए रक्तरंजित और परिणाम में विवादित युद्ध के बाद वालाकिया ने ऑटोमन को खिराज देना स्वीकार किया; डेन्यूब के उत्तर की आश्रित व्यवस्था स्थापित हुई।", "dd69200f"]},
"OLAYLAR_EK:1395-01-01:0":{"b": ["निग़बोलू की विजय", "b9791717"], "d": ["वालाकियाइयों के विरुद्ध की गई 1395 की रोविने लड़ाई के बाद यिल्दिरिम बायज़ीद ने डेन्यूब तट का निग़बोलू दुर्ग ले लिया; कुछ अज्ञात बुल्गार इतिवृत्त विजय के 3 जून 1395 को हुए होने का उल्लेख करते हैं। विजय की तिथि स्रोतों में एक नहीं है: TDV इस्लाम विश्वकोश का निग़बोलू युद्ध लेख लिखता है कि बायज़ीद ने सिलिस्त्रा और निग़बोलू को 1394 के एक डेन्यूब अभियान में हस्तगत किया। दुर्ग 1396 के प्रसिद्ध क्रूसेड अभियान में घेरा जाएगा, परंतु गिरेगा नहीं। उसी तिथि को शामिल हुए अन्य स्थान: ओह्रिद।", "bc450a9f"]},
"OLAYLAR_EK:1395-06-03:0":{"b": ["निग्बोलू दुर्ग ऑटोमन के हाथ में आया", "327012c9"], "d": ["रोविने के आक्रमण के बाद यिल्दिरिम बायज़ीद ने निग्बोलू ले लिया; ऑटोमन सामंत के रूप में वहाँ रहने वाले बुल्गारियाई ज़ार इवान शिशमान को हटा दिया गया। एटलस में निग्बोलू इस दिन से बुल्गारियाई ज़ारशाही से ऑटोमन के नाम दर्ज है।", "6e7d5207"]},
